def auxiliaryCharacterSum (N : Finset ℕ) (alpha : ℕ → ℂ) (k delta : ℕ)
    (chi : DirichletCharacter ℂ delta) : ℂ :=
  ∑ n ∈ N, if n.Coprime k then alpha n * star (chi (n : ZMod delta)) else 0
